major.create_time, major.creator, major.last_modified_time,major.class_id ,
major.applicable_object,
major.last_modifier, major.remark,  major.sysflag,
category.name  category_name
from t_csys_std_major major
left join t_csys_training_scheme_category category
on major.category_id = category.id

     and major.name like concat('%', #{name}, '%')
